local _,K=...
local keys={'cursor','cursorHelp','cursorEnabled','cursorShape','cursorRing','cursorSquare','cursorPlus','cursorSize','cursorAlpha','cursorColor','cursorVisibility','cursorAlways','cursorCombat','cursorPeace','cursorCamera','cursorCameraHelp'}
local rows={
 en={'Mouse Cursor','A simple cursor indicator. Off by default. Settings apply immediately and are shared by your characters. Tracking stops when disabled or hidden by the combat visibility setting.','Enable cursor indicator','Shape','Ring','Square','Plus','Size','Opacity','Choose color','Visibility','Always','In combat','Out of combat','Keep visible while turning the camera','While turning the camera, the indicator stays at the last cursor position. No GCD or cast-time rings in this first version.'},
 tr={'Fare İmleci','Sade bir imleç göstergesi. Başlangıçta kapalıdır. Ayarlar anında uygulanır ve karakterler arasında ortaktır. Kapalıyken veya savaş görünürlük koşulu sağlanmıyorken takip durur.','İmleç göstergesini aç','Şekil','Halka','Kare','Artı','Boyut','Görünürlük oranı','Renk seç','Görünürlük','Her zaman','Savaşta','Savaş dışında','Kamera çevirirken görünür kalsın','Kamera çevirirken gösterge son imleç konumunda kalır. Bu ilk sürümde GCD ve büyü süresi halkaları bulunmaz.'},
 de={'Mauszeiger','Eine schlichte Mauszeigeranzeige. Anfangs ausgeschaltet. Änderungen gelten sofort für alle Charaktere. Bei deaktivierter Anzeige oder nicht erfüllter Kampfbedingung stoppt die Verfolgung.','Mauszeigeranzeige aktivieren','Form','Ring','Quadrat','Plus','Größe','Deckkraft','Farbe wählen','Sichtbarkeit','Immer','Im Kampf','Außerhalb des Kampfes','Beim Drehen der Kamera sichtbar bleiben','Beim Drehen der Kamera bleibt die Anzeige an der letzten Mausposition. Diese erste Version enthält keine GCD- oder Zauberzeitringe.'},
 frFR={'Curseur','Un indicateur de curseur simple, désactivé par défaut. Réglages immédiats et communs aux personnages. Le suivi cesse si désactivé ou masqué par la condition de combat.','Activer l’indicateur','Forme','Anneau','Carré','Plus','Taille','Opacité','Choisir la couleur','Visibilité','Toujours','En combat','Hors combat','Rester visible pendant la rotation de caméra','Pendant la rotation de caméra, l’indicateur reste à la dernière position du curseur. Cette version ne comprend aucun anneau de recharge globale ou d’incantation.'},
 itIT={'Cursore','Un semplice indicatore, inizialmente disattivato. Impostazioni immediate e condivise tra i personaggi. Il tracciamento si ferma se disattivato o nascosto dalla condizione di combattimento.','Attiva indicatore','Forma','Anello','Quadrato','Più','Dimensione','Opacità','Scegli colore','Visibilità','Sempre','In combattimento','Fuori combattimento','Resta visibile ruotando la visuale','Ruotando la visuale, l’indicatore resta nell’ultima posizione del cursore. Questa versione non include anelli di recupero globale o lancio.'},
 esES={'Cursor','Un indicador sencillo, desactivado por defecto. Los ajustes se aplican al instante y se comparten entre personajes. El seguimiento se detiene al desactivarlo o si la condición de combate lo oculta.','Activar indicador','Forma','Anillo','Cuadrado','Más','Tamaño','Opacidad','Elegir color','Visibilidad','Siempre','En combate','Fuera de combate','Visible al girar la cámara','Al girar la cámara, el indicador permanece en la última posición del cursor. Esta versión no incluye anillos de reutilización global ni de lanzamiento.'},
 ptBR={'Cursor','Um indicador simples, desativado por padrão. Ajustes imediatos e compartilhados entre personagens. O rastreamento para quando desativado ou oculto pela condição de combate.','Ativar indicador','Forma','Anel','Quadrado','Mais','Tamanho','Opacidade','Escolher cor','Visibilidade','Sempre','Em combate','Fora de combate','Manter visível ao girar a câmera','Ao girar a câmera, o indicador fica na última posição do cursor. Esta versão não inclui anéis de recarga global ou lançamento.'},
 ruRU={'Курсор','Простой индикатор, изначально выключен. Настройки применяются сразу для всех персонажей. Отслеживание прекращается при отключении или скрытии по условию боя.','Включить индикатор','Форма','Кольцо','Квадрат','Плюс','Размер','Непрозрачность','Выбрать цвет','Видимость','Всегда','В бою','Вне боя','Показывать при вращении камеры','При вращении камеры индикатор остаётся в последней позиции курсора. В этой версии нет колец общего восстановления и времени произнесения.'},
 zhCN={'鼠标指针','简单的鼠标指示器，默认关闭。设置立即生效，所有角色共用。关闭或因战斗条件而隐藏时停止跟踪。','启用鼠标指示器','形状','圆环','方框','十字','大小','不透明度','选择颜色','显示条件','始终','战斗中','非战斗时','转动镜头时保持显示','转动镜头时，指示器停留在鼠标的最后位置。此初始版本不包含公共冷却或施法时间圆环。'}
}
for code,row in pairs(rows)do
 assert(#row==#keys,'Cursor locale key count')
 for i,key in ipairs(keys)do K.locales[code][key]=row[i]end
end
local timingKeys={'cursorGCD','cursorCast','cursorTimingHelp','cursorCameraHelp'}
local timingRows={
 en={'Show global cooldown (GCD) ring','Show cast and channel ring','Inner blue ring: GCD. Outer ring: your cast or channel, white at first and gradually red near completion. Rings appear only while timing. Both options are off by default.','While turning the camera, the indicator stays at the last cursor position.'},
 tr={'Global cooldown (GCD) halkasını göster','Büyü ve kanal süresi halkasını göster','İçteki mavi halka: GCD. En dıştaki halka: yaptığın büyü veya kanal; beyaz başlar, bitişe yaklaştıkça kırmızıya döner. Halkalar yalnız süre işlerken görünür. İki seçenek de başlangıçta kapalıdır.','Kamera çevirirken gösterge son imleç konumunda kalır.'},
 de={'Ring für globale Abklingzeit (GCD) anzeigen','Zauber- und Kanalisierungsring anzeigen','Innerer blauer Ring: GCD. Äußerer Ring: eigener Zauber oder Kanalisierung, erst weiß und zum Ende hin rot. Ringe erscheinen nur während der Laufzeit. Beide Optionen sind anfangs aus.','Beim Drehen der Kamera bleibt die Anzeige an der letzten Mausposition.'},
 frFR={'Afficher l’anneau de recharge globale (GCD)','Afficher l’anneau d’incantation et de canalisation','Anneau bleu intérieur : recharge globale. Anneau extérieur : votre incantation ou canalisation, blanc puis progressivement rouge vers la fin. Visibles uniquement pendant leur durée. Options désactivées par défaut.','Pendant la rotation de caméra, l’indicateur reste à la dernière position du curseur.'},
 itIT={'Mostra anello di recupero globale (GCD)','Mostra anello di lancio e canalizzazione','Anello blu interno: recupero globale. Anello esterno: il tuo lancio o canalizzazione, bianco all’inizio e gradualmente rosso verso la fine. Visibili solo durante la durata. Opzioni inizialmente disattivate.','Ruotando la visuale, l’indicatore resta nell’ultima posizione del cursore.'},
 esES={'Mostrar anillo de reutilización global (GCD)','Mostrar anillo de lanzamiento y canalización','Anillo azul interior: reutilización global. Anillo exterior: tu lanzamiento o canalización, blanco al principio y rojo al acercarse al final. Solo visibles mientras transcurre su duración. Desactivados por defecto.','Al girar la cámara, el indicador permanece en la última posición del cursor.'},
 ptBR={'Mostrar anel de recarga global (GCD)','Mostrar anel de lançamento e canalização','Anel azul interno: recarga global. Anel externo: seu lançamento ou canalização, branco no início e gradualmente vermelho perto do fim. Visíveis apenas durante a duração. Opções desativadas por padrão.','Ao girar a câmera, o indicador fica na última posição do cursor.'},
 ruRU={'Показывать кольцо общего восстановления (GCD)','Показывать кольцо произнесения и поддержания','Внутреннее синее кольцо: общее восстановление. Внешнее: ваше произнесение или поддержание, сначала белое, к концу красное. Видны только во время отсчёта. Обе настройки изначально выключены.','При вращении камеры индикатор остаётся в последней позиции курсора.'},
 zhCN={'显示公共冷却（GCD）圆环','显示施法和引导圆环','内侧蓝色圆环表示公共冷却。最外侧圆环表示自己的施法或引导，开始为白色，接近结束时逐渐变红。仅在计时期间显示。两个选项默认关闭。','转动镜头时，指示器停留在鼠标的最后位置。'}
}
for code,row in pairs(timingRows)do
 assert(#row==#timingKeys,'Cursor timing locale key count')
 for i,key in ipairs(timingKeys)do K.locales[code][key]=row[i]end
end
local extraKeys={'cursorReticle','cursorThickness','cursorDot','cursorDotCamera','cursorCountdown','cursorTrail','cursorExtrasHelp'}
local extraRows={
 en={'Reticle','Line thickness','Show center dot','Hide center dot while turning the camera','Show remaining cast seconds in the center','Show short movement trail','Thickness changes the main shape. The center dot can disappear while turning the camera. Cast seconds use the game’s countdown and temporarily replace the dot. The short trail uses up to eight fading dots; off by default.'},
 tr={'Nişangâh','Çizgi kalınlığı','Ortada nokta göster','Kamera çevirirken ortadaki noktayı gizle','Büyü sırasında ortada kalan saniyeyi göster','Kısa hareket izini göster','Kalınlık ana şekli değiştirir. Ortadaki nokta kamera çevirirken gizlenebilir. Kalan büyü saniyesi oyunun sayacıyla gösterilir; bu sırada noktanın yerini alır. Kısa iz en fazla sekiz sönümlenen nokta kullanır; başlangıçta kapalıdır.'},
 de={'Fadenkreuz','Linienstärke','Punkt in der Mitte anzeigen','Punkt beim Drehen der Kamera ausblenden','Verbleibende Zaubersekunden in der Mitte anzeigen','Kurze Bewegungsspur anzeigen','Die Stärke ändert die Hauptform. Der Punkt kann beim Drehen der Kamera verschwinden. Die Zauberzeit nutzt den Spiel-Countdown und ersetzt vorübergehend den Punkt. Die kurze Spur nutzt bis zu acht verblassende Punkte; anfangs aus.'},
 frFR={'Réticule','Épaisseur du trait','Afficher le point central','Masquer le point en tournant la caméra','Afficher les secondes d’incantation au centre','Afficher une courte traînée','L’épaisseur modifie la forme principale. Le point peut disparaître pendant la rotation de caméra. Le décompte du jeu remplace temporairement le point. La traînée utilise huit points au maximum ; désactivée par défaut.'},
 itIT={'Mirino','Spessore della linea','Mostra punto centrale','Nascondi punto ruotando la visuale','Mostra i secondi di lancio rimasti al centro','Mostra breve scia di movimento','Lo spessore cambia la forma principale. Il punto può sparire ruotando la visuale. Il conto del gioco sostituisce temporaneamente il punto. La scia usa al massimo otto punti che svaniscono; inizialmente disattivata.'},
 esES={'Retícula','Grosor de línea','Mostrar punto central','Ocultar punto al girar la cámara','Mostrar segundos de lanzamiento en el centro','Mostrar estela corta','El grosor cambia la forma principal. El punto puede ocultarse al girar la cámara. La cuenta del juego sustituye temporalmente el punto. La estela usa hasta ocho puntos que se desvanecen; desactivada por defecto.'},
 ptBR={'Mira','Espessura da linha','Mostrar ponto central','Ocultar ponto ao girar a câmera','Mostrar segundos de lançamento no centro','Mostrar rastro curto','A espessura muda a forma principal. O ponto pode sumir ao girar a câmera. A contagem do jogo substitui o ponto temporariamente. O rastro usa até oito pontos que desaparecem; desativado por padrão.'},
 ruRU={'Прицел','Толщина линий','Показывать точку в центре','Скрывать точку при вращении камеры','Показывать оставшиеся секунды в центре','Показывать короткий след','Толщина меняет основную фигуру. Точка может скрываться при вращении камеры. Игровой отсчёт временно заменяет точку. Короткий след использует не более восьми затухающих точек; изначально выключен.'},
 zhCN={'准星','线条粗细','显示中心点','转动镜头时隐藏中心点','在中心显示施法剩余秒数','显示短移动轨迹','粗细设置影响主形状。中心点可在转动镜头时隐藏。施法剩余秒数使用游戏倒计时，暂时替代中心点。短轨迹最多使用八个渐隐点，默认关闭。'}
}
for code,row in pairs(extraRows)do
 assert(#row==#extraKeys,'Cursor extra locale key count')
 for i,key in ipairs(extraKeys)do K.locales[code][key]=row[i]end
end
local lightKeys={'cursorLight','cursorTrail','cursorExtrasHelp'}
local lightRows={
 en={'Light','Show light trail','Light uses a bright point with a soft halo. The continuous trail fades after movement stops and clears while turning the camera. The dot can hide during camera movement; cast seconds replace it while casting.'},
 tr={'Işık','Işık izini göster','Işık şekli, parlak bir nokta ve çevresindeki ışık halesidir. Kesintisiz iz hareket durunca söner; kamera çevirirken temizlenir. Nokta kamera hareketinde gizlenebilir; büyü sırasında saniye sayacı noktanın yerini alır.'},
 de={'Licht','Lichtspur anzeigen','Licht zeigt einen hellen Punkt mit einem sanften Schein. Die durchgehende Spur verblasst nach dem Anhalten und verschwindet beim Drehen der Kamera. Der Punkt kann dabei verborgen werden; die Zauberzeit ersetzt ihn während des Zauberns.'},
 frFR={'Lumière','Afficher la traînée lumineuse','Lumière affiche un point brillant entouré d’un halo. La traînée continue s’efface après l’arrêt et disparaît pendant la rotation de caméra. Le point peut se masquer avec la caméra ; le décompte le remplace pendant une incantation.'},
 itIT={'Luce','Mostra scia luminosa','Luce mostra un punto brillante con un alone. La scia continua svanisce quando il movimento si ferma e si cancella ruotando la visuale. Il punto può nascondersi con la visuale; i secondi lo sostituiscono durante il lancio.'},
 esES={'Luz','Mostrar estela luminosa','Luz muestra un punto brillante con un halo. La estela continua se desvanece al detenerse y desaparece al girar la cámara. El punto puede ocultarse con la cámara; los segundos lo sustituyen durante el lanzamiento.'},
 ptBR={'Luz','Mostrar rastro luminoso','Luz mostra um ponto brilhante com um halo. O rastro contínuo desaparece ao parar e é limpo ao girar a câmera. O ponto pode sumir com a câmera; os segundos o substituem durante o lançamento.'},
 ruRU={'Свет','Показывать световой след','Свет — яркая точка с ореолом. Непрерывный след затухает после остановки и исчезает при вращении камеры. Точка может скрываться с камерой; при произнесении её заменяет отсчёт секунд.'},
 zhCN={'光点','显示光线轨迹','光点形状显示明亮的中心和光晕。连续轨迹在停止移动后渐隐，转动镜头时清除。中心点可在转动镜头时隐藏，施法期间由剩余秒数替代。'}
}
for code,row in pairs(lightRows)do
 for i,key in ipairs(lightKeys)do K.locales[code][key]=row[i]end
end
local effectKeys={'cursorGCDGap','cursorCastGap','cursorEffectStyle','cursorRibbon','cursorSparkles','cursorRibbonSparkles','cursorEffectsHelp'}
local effectRows={
 en={'GCD ring distance','Cast ring distance','Movement effect','Light ribbon','Sparkles','Light + sparkles','Reduce the distances to bring rings closer; 0 is the closest position. GCD distance is measured from the main shape, cast distance from the nearest inner ring. Choose a ribbon, fading sparkles, or both. Effects fade when movement stops.'},
 tr={'GCD halkası mesafesi','Büyü halkası mesafesi','Hareket efekti','Işık şeridi','Işıltı','Işık + Işıltı','Mesafeleri azaltarak halkaları yaklaştırabilirsin; 0 en yakın konumdur. GCD mesafesi ana şekilden, büyü mesafesi en yakın iç halkadan ölçülür. Işık şeridi, sönümlenen ışıltılar veya ikisini birlikte seçebilirsin. Hareket durunca efekt söner.'},
 de={'Abstand des GCD-Rings','Abstand des Zauberrings','Bewegungseffekt','Lichtband','Funkeln','Licht + Funkeln','Kleinere Abstände rücken die Ringe näher; 0 ist am nächsten. GCD-Abstand gilt ab der Hauptform, Zauberabstand ab dem nächsten inneren Ring. Lichtband, verblassendes Funkeln oder beides wählen. Nach dem Anhalten verblasst der Effekt.'},
 frFR={'Distance de l’anneau GCD','Distance de l’anneau de sort','Effet de mouvement','Ruban lumineux','Étincelles','Lumière + étincelles','Réduisez les distances pour rapprocher les anneaux ; 0 est le plus proche. Le GCD part de la forme principale, le sort de l’anneau intérieur le plus proche. Choisissez ruban, étincelles ou les deux. L’effet s’efface après l’arrêt.'},
 itIT={'Distanza anello GCD','Distanza anello lancio','Effetto di movimento','Scia luminosa','Scintille','Luce + scintille','Riduci le distanze per avvicinare gli anelli; 0 è il minimo. Il GCD parte dalla forma principale, il lancio dall’anello interno più vicino. Scegli scia, scintille o entrambi. L’effetto svanisce quando ti fermi.'},
 esES={'Distancia del anillo GCD','Distancia del anillo de lanzamiento','Efecto de movimiento','Cinta luminosa','Destellos','Luz + destellos','Reduce las distancias para acercar los anillos; 0 es lo más cercano. El GCD parte de la forma principal, el lanzamiento del anillo interior más próximo. Elige cinta, destellos o ambos. El efecto se desvanece al detenerse.'},
 ptBR={'Distância do anel GCD','Distância do anel de lançamento','Efeito de movimento','Faixa de luz','Brilhos','Luz + brilhos','Reduza as distâncias para aproximar os anéis; 0 é o mais próximo. O GCD parte da forma principal, o lançamento do anel interno mais próximo. Escolha faixa, brilhos ou ambos. O efeito desaparece ao parar.'},
 ruRU={'Расстояние кольца GCD','Расстояние кольца произнесения','Эффект движения','Световая лента','Искры','Лента + искры','Уменьшите расстояния, чтобы приблизить кольца; 0 — ближайшее положение. GCD отсчитывается от основной фигуры, произнесение — от ближайшего внутреннего кольца. Выберите ленту, искры или оба эффекта. После остановки эффект затухает.'},
 zhCN={'公共冷却圆环间距','施法圆环间距','移动效果','光线轨迹','闪光','光线 + 闪光','减小间距可让圆环更靠近，0为最近位置。公共冷却间距从主形状计算，施法间距从最近的内侧圆环计算。可选光线、渐隐闪光或两者。停止移动后效果渐隐。'}
}
for code,row in pairs(effectRows)do
 assert(#row==#effectKeys,'Cursor effect locale key count')
 for i,key in ipairs(effectKeys)do K.locales[code][key]=row[i]end
end
local nativeKeys={'cursorNativeBlueFlow','cursorNativeBlueArc','cursorNativeGreenArc','cursorNativeTitle','cursorNativeScale','cursorNativeAlpha','cursorNativeX','cursorNativeY','cursorNativeHelp','cursorNativeUnavailable'}
local nativeRows={
 en={'Game: Blue flow','Game: Blue electric','Game: Green electric','Game effect settings','Effect size','Effect opacity','Horizontal alignment','Vertical alignment','These settings affect only the three Game effects. They use their own game colors; the main shape keeps your selected color. Effects fade when idle and stop while turning the camera. Adjust alignment if the bright tip misses the cursor.','Game effect unavailable; using the light ribbon instead.'},
 tr={'Oyun: Mavi akış','Oyun: Mavi elektrik','Oyun: Yeşil elektrik','Oyun efekti ayarları','Efekt boyutu','Efekt görünürlük oranı','Yatay hizalama','Dikey hizalama','Bu ayarlar yalnız üç Oyun efektini değiştirir. Efektler oyundaki kendi renklerini kullanır; ana şekil seçtiğin renkte kalır. Durunca söner, kamera çevirirken durur. Parlak uç imlece oturmazsa hizalamayı ayarlayabilirsin.','Oyun efekti yüklenemedi; ışık şeridi kullanılıyor.'},
 de={'Spiel: Blauer Fluss','Spiel: Blauer Blitz','Spiel: Grüner Blitz','Spieleffekt-Einstellungen','Effektgröße','Effektdeckkraft','Horizontale Ausrichtung','Vertikale Ausrichtung','Diese Einstellungen gelten nur für die drei Spieleffekte. Sie nutzen ihre eigenen Farben; die Hauptform behält die gewählte Farbe. Im Stillstand verblassen sie, beim Drehen der Kamera stoppen sie. Bei Bedarf die helle Spitze am Zeiger ausrichten.','Spieleffekt nicht verfügbar; stattdessen wird das Lichtband verwendet.'},
 frFR={'Jeu : flux bleu','Jeu : éclair bleu','Jeu : éclair vert','Réglages des effets du jeu','Taille de l’effet','Opacité de l’effet','Alignement horizontal','Alignement vertical','Ces réglages concernent les trois effets du jeu. Ils gardent leurs propres couleurs ; la forme principale conserve votre couleur. Ils s’effacent à l’arrêt et cessent en tournant la caméra. Ajustez l’alignement de la pointe si nécessaire.','Effet du jeu indisponible ; utilisation du ruban lumineux.'},
 itIT={'Gioco: flusso blu','Gioco: fulmine blu','Gioco: fulmine verde','Impostazioni effetti del gioco','Dimensione effetto','Opacità effetto','Allineamento orizzontale','Allineamento verticale','Queste impostazioni valgono solo per i tre effetti del gioco. Usano i propri colori; la forma principale mantiene il tuo colore. Svaniscono da fermi e si fermano ruotando la visuale. Regola l’allineamento della punta se necessario.','Effetto del gioco non disponibile; viene usata la scia luminosa.'},
 esES={'Juego: flujo azul','Juego: rayo azul','Juego: rayo verde','Ajustes de efectos del juego','Tamaño del efecto','Opacidad del efecto','Alineación horizontal','Alineación vertical','Estos ajustes afectan solo a los tres efectos del juego. Usan sus propios colores; la forma principal conserva tu color. Se atenúan al parar y cesan al girar la cámara. Ajusta la punta al cursor si hace falta.','Efecto del juego no disponible; se usa la cinta luminosa.'},
 ptBR={'Jogo: fluxo azul','Jogo: raio azul','Jogo: raio verde','Ajustes dos efeitos do jogo','Tamanho do efeito','Opacidade do efeito','Alinhamento horizontal','Alinhamento vertical','Estes ajustes valem apenas para os três efeitos do jogo. Eles usam suas próprias cores; a forma principal mantém sua cor. Desaparecem ao parar e param ao girar a câmera. Ajuste o alinhamento da ponta se necessário.','Efeito do jogo indisponível; usando a faixa de luz.'},
 ruRU={'Игра: синий поток','Игра: синяя молния','Игра: зелёная молния','Настройки игровых эффектов','Размер эффекта','Непрозрачность эффекта','Горизонтальное смещение','Вертикальное смещение','Эти настройки влияют только на три игровых эффекта. У них собственные цвета; основная фигура сохраняет ваш цвет. Эффекты затухают при остановке и прекращаются при вращении камеры. При необходимости совместите яркий кончик с курсором.','Игровой эффект недоступен; используется световая лента.'},
 zhCN={'游戏：蓝色流光','游戏：蓝色闪电','游戏：绿色闪电','游戏效果设置','效果大小','效果不透明度','水平对齐','垂直对齐','这些设置仅影响三种游戏效果。效果使用游戏自带颜色，主形状保留所选颜色。停止移动后渐隐，转动镜头时停止。如果亮点偏离鼠标，可调整对齐。','游戏效果不可用，已改用光线轨迹。'}
}
for code,row in pairs(nativeRows)do
 assert(#row==#nativeKeys,'Cursor native locale key count')
 for i,key in ipairs(nativeKeys)do K.locales[code][key]=row[i]end
end
local policyKeys={'cursorNativeCamera','cursorNativeFadeIdle','cursorNativePolicyHelp'}
local policyRows={
 en={'Show game effect while turning the camera','Fade game effect when the mouse stops','Camera display is off by default; if enabled, the effect stays at the last cursor position. Idle fading is separate. Old trails clear briefly after a jump before the effect becomes visible again. The effect does not track players or targets.'},
 tr={'Kamera çevirirken oyun efektini göster','Fare durunca oyun efektini söndür','Kamera görünümü başlangıçta kapalıdır; açarsan efekt son imleç konumunda kalır. Durunca sönme ayrı seçenektir. Konum sıçramasından sonra eski izler temizlenirken efekt kısa süre gizlenir. Oyuncu veya hedef konumunu takip etmez.'},
 de={'Spieleffekt beim Drehen der Kamera anzeigen','Spieleffekt bei stillstehender Maus ausblenden','Die Kameraanzeige ist anfangs aus. Aktiviert bleibt der Effekt an der letzten Mausposition. Verblassen im Stillstand ist separat. Nach Positionssprüngen werden alte Spuren kurz unsichtbar bereinigt. Spieler und Ziele werden nicht verfolgt.'},
 frFR={'Afficher l’effet en tournant la caméra','Atténuer l’effet quand la souris s’arrête','L’affichage avec la caméra est désactivé au départ. Activé, l’effet reste à la dernière position du curseur. L’atténuation à l’arrêt est séparée. Après un saut, les anciennes traces sont brièvement masquées. Aucun joueur ni cible n’est suivi.'},
 itIT={'Mostra effetto ruotando la visuale','Dissolvi effetto quando il mouse si ferma','La visualizzazione con la camera è inizialmente disattivata. Se attiva, l’effetto resta all’ultima posizione del cursore. La dissolvenza da fermi è separata. Dopo un salto, le vecchie scie vengono nascoste brevemente. Non segue giocatori o bersagli.'},
 esES={'Mostrar efecto al girar la cámara','Desvanecer efecto al detener el ratón','La vista con cámara está desactivada al principio. Si se activa, el efecto permanece en la última posición del cursor. El desvanecimiento al parar es independiente. Tras un salto se ocultan brevemente las estelas antiguas. No sigue jugadores ni objetivos.'},
 ptBR={'Mostrar efeito ao girar a câmera','Apagar efeito quando o mouse parar','A exibição com câmera começa desativada. Ativada, mantém o efeito na última posição do cursor. O desaparecimento ao parar é separado. Após um salto, rastros antigos são ocultos brevemente. Não segue jogadores nem alvos.'},
 ruRU={'Показывать эффект при вращении камеры','Гасить эффект при остановке мыши','Показ с камерой изначально выключен. При включении эффект остаётся в последней позиции курсора. Затухание при остановке настраивается отдельно. После скачка старые следы ненадолго скрываются. Игроки и цели не отслеживаются.'},
 zhCN={'转动镜头时显示游戏效果','鼠标停止时淡出游戏效果','镜头显示默认关闭。开启后效果停留在鼠标最后的位置。停止时淡出是独立选项。位置跳变后会短暂隐藏旧轨迹。效果不会追踪玩家或目标。'}
}
for code,row in pairs(policyRows)do
 assert(#row==#policyKeys,'Cursor policy locale key count')
 for i,key in ipairs(policyKeys)do K.locales[code][key]=row[i]end
end
local nativeHelpRows={
 en='Game effects keep their own colors; the main shape keeps your chosen color. Size and alignment below apply only to game effects. Camera display and fading at rest are separate choices. The first appearance is delayed briefly while old ribbon segments clear.',
 tr='Oyun efektleri kendi renklerini, ana şekil seçtiğin rengi kullanır. Boyut ve hizalama yalnız oyun efektine uygulanır. Kamera görünümü ile durunca sönme ayrı seçeneklerdir. İlk görünüm, eski izler temizlenirken kısa süre gecikebilir.',
 de='Spieleffekte behalten ihre Farben, die Hauptform Ihre gewählte Farbe. Größe und Ausrichtung gelten nur für Spieleffekte. Kameraanzeige und Verblassen im Stillstand sind getrennt. Alte Spuren werden vor dem ersten Erscheinen kurz bereinigt.',
 frFR='Les effets du jeu gardent leurs couleurs et la forme principale votre couleur. Taille et alignement concernent uniquement les effets du jeu. Caméra et atténuation à l’arrêt sont séparées. Un bref délai efface les anciennes traces avant l’apparition.',
 itIT='Gli effetti del gioco mantengono i propri colori e la forma principale il tuo colore. Dimensione e allineamento riguardano solo gli effetti del gioco. Visuale e dissolvenza da fermi sono separate. Un breve ritardo elimina le vecchie scie prima della comparsa.',
 esES='Los efectos del juego conservan sus colores y la forma principal el tuyo. Tamaño y alineación solo afectan a los efectos del juego. Cámara y desvanecimiento al parar son independientes. Un breve retraso elimina las estelas antiguas antes de aparecer.',
 ptBR='Os efeitos do jogo mantêm suas cores e a forma principal mantém a sua. Tamanho e alinhamento afetam apenas efeitos do jogo. Câmera e desaparecimento ao parar são separados. Um pequeno atraso limpa rastros antigos antes de aparecer.',
 ruRU='Игровые эффекты сохраняют свои цвета, основная фигура — выбранный цвет. Размер и смещение относятся только к игровым эффектам. Камера и затухание при остановке настраиваются отдельно. Перед появлением старые следы кратко очищаются.',
 zhCN='游戏效果保留自带颜色，主形状保留所选颜色。大小和对齐仅影响游戏效果。镜头显示与停止时淡出是独立选项。首次出现前会短暂等待旧轨迹清除。'
}
for code,value in pairs(nativeHelpRows)do K.locales[code].cursorNativeHelp=value end

